class Repo:
    def find_by_id(self, item_id):
        rows = {"x1": {"title": "Alpha"}}
        return rows.get(item_id)

def get_item(repo, item_id):
    row = repo.find_by_id(item_id)
    if row is None:
        return "not found"
    return row["title"]

repo = Repo()
happy_pass = get_item(repo, "x1") == "Alpha"
print(happy_pass)

